{"path": "/workspace/target/src/keys.py", "content": """"Canonical parsing of serving-request key columns.

Production requests are serialized: identifier and code columns arrive as
strings (sometimes padded, sometimes carrying a redundant ``.0`` tail), as
floats, or as native integers.  Offline parquet slices publish the same
columns as 32-bit or 64-bit integers, and any column that carries a missing
value in a release is published as floating point.  Every join against the
lookup tables therefore has to go through one canonical integer form.
"""
from __future__ import annotations

import math
from typing import Any, Optional

import numpy as np
import pandas as pd

UNKNOWN = "UNKNOWN"


def parse_key(value: Any) -> Optional[int]:
    """Return the integral key encoded by ``value`` or ``None``.

    Accepts ints, floats with an integral value, numpy scalars, and strings
    that may be padded with whitespace and/or written in decimal form.
    Anything else (blank, missing, non-numeric, fractional) has no key.
    """
    if value is None:
        return None
    if isinstance(value, (bool, np.bool_)):
        return None
    if isinstance(value, (int, np.integer)):
        return int(value)
    if isinstance(value, (float, np.floating)):
        number = float(value)
        if math.isnan(number) or math.isinf(number):
            return None
        return int(round(number)) if float(number).is_integer() else None
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return None
        try:
            number = float(text)
        except ValueError:
            return None
        if math.isnan(number) or math.isinf(number):
            return None
        return int(round(number)) if number.is_integer() else None
    try:
        if pd.isna(value):
            return None
    except (TypeError, ValueError):
        pass
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    if math.isnan(number) or math.isinf(number):
        return None
    return int(round(number)) if float(number).is_integer() else None


def parse_keys(values: pd.Series) -> pd.Series:
    """Vectorised :func:`parse_key` returning a nullable Int64 series."""
    if pd.api.types.is_integer_dtype(values.dtype):
        return values.astype("Int64")
    return pd.Series(
        [parse_key(value) for value in values],
        index=values.index,
        dtype="Int64",
    )


def is_missing(value: Any) -> bool:
    """True when a serving field is absent rather than merely unparseable."""
    if value is None:
        return True
    if isinstance(value, str):
        return value.strip() == ""
    try:
        return bool(pd.isna(value))
    except (TypeError, ValueError):
        return False
"}

{"path": "/workspace/target/src/serve.py", "content": "from __future__ import annotations

from pathlib import Path
from typing import Any, Mapping, Sequence

import pandas as pd

from . import enrich, features, model, time_contract

DATA = Path(__file__).resolve().parent.parent / "data"

CONTRACT_COLUMNS = list(enrich.CONTRACT_COLUMNS)


def load_reference() -> tuple[pd.DataFrame, pd.DataFrame]:
    # Keep every lookup cell exactly as published: no dtype coercion and no
    # NA-token guessing, so blank cells stay blank and codes stay resolvable.
    zones = pd.read_csv(DATA / "taxi_zone_lookup.csv", dtype=str, keep_default_na=False)
    rates = pd.read_csv(DATA / "rate_codes.csv", dtype=str, keep_default_na=False)
    return zones, rates


def to_frame(records: Any) -> pd.DataFrame:
    """Accept a single request mapping, a sequence of them, or a DataFrame."""
    if isinstance(records, pd.DataFrame):
        return records
    if isinstance(records, Mapping):
        return pd.DataFrame([dict(records)])
    if isinstance(records, Sequence):
        return pd.DataFrame([dict(record) for record in records])
    raise TypeError(f"unsupported request payload: {type(records)!r}")


def enrich_batch(trips: Any) -> pd.DataFrame:
    zones, rates = load_reference()
    return enrich.enrich(to_frame(trips), zones, rates)


def contract_batch(trips: Any) -> pd.DataFrame:
    """Return only the serving contract columns for a batch of requests."""
    enriched = enrich_batch(trips)
    return enriched.loc[:, CONTRACT_COLUMNS].copy()


def enrich_record(record: Mapping) -> dict:
    """Resolve the serving contract for a single request."""
    frame = contract_batch(record)
    return {column: str(frame.iloc[0][column]) for column in CONTRACT_COLUMNS}


def build_matrix(trips: Any) -> pd.DataFrame:
    zones, rates = load_reference()
    return features.build(to_frame(trips), zones, rates)


def score_batch(estimator, trips: Any) -> pd.Series:
    matrix = build_matrix(to_frame(trips))
    return pd.Series(estimator.predict(matrix), name="predicted_duration_minutes")
"}

